        raise GateInputError(f"{where}: {what} must be a finite number{' or null' if nullable else ''}, got {v!r}")
    return float(v)


def load(path: Path) -> dict[str, Skill]:
    skills: dict[str, Skill] = {}
    seen: dict[tuple, str] = {}
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError as e:
        raise GateInputError(f"cannot read {path}: {e}") from e
    for n, line in enumerate(lines, 1):
        if not line.strip():
            continue
        where = f"{path.name} line {n}"
        try:
            row = json.loads(line)
        except json.JSONDecodeError as e:
            raise GateInputError(f"{where}: not valid JSON ({e.msg})") from e
        if not isinstance(row, dict):
            raise GateInputError(f"{where}: expected a JSON object")
        missing = [k for k in REQUIRED if k not in row]
        if missing:
            raise GateInputError(f"{where}: missing field(s) {', '.join(missing)}")
        name, task = str(row["skill"]), str(row["task_id"])
        key = (name, task, row["rep"])
        if key in seen:
            raise GateInputError(f"{where}: duplicate run (skill {name}, task {task}, rep {row['rep']}), first seen at {seen[key]}")
        seen[key] = where
        s = skills.setdefault(name, Skill(name))
        s.rewards.setdefault(task, []).append(_number(row["reward"], "reward", where, nullable=True))
        s.costs.setdefault(task, []).append(_number(row["cost"], "cost", where, nullable=True))
        if row.get("cost_metric") is not None:
            s.metrics.add(str(row["cost_metric"]))
    return skills


def _sem(xs: list[float]) -> float:
    return statistics.stdev(xs) / math.sqrt(len(xs))


def _mean_cost(s: Skill, tasks: list[str]) -> float | None:
    costs = [s.task_cost(t) for t in tasks]
    return None if any(c is None for c in costs) else statistics.fmean(costs)


@dataclass
class Comparison:
    candidate: str
    current: str
    d: float
    se: float
    se_kind: str
    n_candidate: int
    n_current: int
    acc_candidate: float
    acc_current: float
    cost_candidate: float | None
    cost_current: float | None
    dropped_tasks: list[str]


def compare(cand: Skill, cur: Skill) -> Comparison:
    """d and SE for cand minus cur. Tasks where cur has an ungraded run are dropped from both."""
    dropped = cur.ungraded()
    c_tasks = sorted(t for t in cand.rewards if t not in dropped)
    k_tasks = sorted(t for t in cur.rewards if t not in dropped)
    for s, tasks in ((cand, c_tasks), (cur, k_tasks)):
        if len(tasks) < 2:
            raise GateInputError(
                f"skill {s.name} has {len(tasks)} usable task(s) against {cand.name if s is cur else cur.name}; "
                "the standard error needs at least 2")
    c_acc = statistics.fmean(cand.task_reward(t) for t in c_tasks)
    k_acc = statistics.fmean(cur.task_reward(t) for t in k_tasks)
    if c_tasks == k_tasks:
        diffs = [cand.task_reward(t) - cur.task_reward(t) for t in c_tasks]
        se, kind = _sem(diffs), "paired"
    else:
        se = math.hypot(_sem([cand.task_reward(t) for t in c_tasks]), _sem([cur.task_reward(t) for t in k_tasks]))
        kind = "unpaired"
    return Comparison(cand.name, cur.name, c_acc - k_acc, se, kind, len(c_tasks), len(k_tasks),
                      c_acc, k_acc, _mean_cost(cand, c_tasks), _mean_cost(cur, k_tasks), dropped)


def verdict(c: Comparison) -> tuple[bool, str]:
    acc = f"reward {c.acc_candidate:.4f} vs {c.acc_current:.4f}, d {c.d:+.4f}, SE {c.se:.4f} ({c.se_kind})"
    if c.d > c.se + EPS:
        return True, f"more accurate: {acc}"
    if c.d < -c.se - EPS:
        return False, f"less accurate: {acc}"
    if c.cost_candidate is None or c.cost_current is None:
        return False, f"tie within 1 SE, cost not comparable (a cost is null): {acc}"
    cost = f"cost {c.cost_candidate:.4g} vs {c.cost_current:.4g}"
    if c.cost_candidate < c.cost_current - EPS:
        return True, f"tie within 1 SE, cheaper: {acc}; {cost}"
    return False, f"tie within 1 SE, not cheaper: {acc}; {cost}"


def judge(skills: dict[str, Skill], current: str, candidates: list[str]) -> dict:
    for name in [current, *candidates]:
        if name not in skills:
            raise GateInputError(f"skill {name!r} has no runs in the file (found: {', '.join(sorted(skills))})")
    if current in candidates:
        raise GateInputError(f"{current!r} is both the current skill and a candidate")
    metrics = set().union(*(skills[n].metrics for n in [current, *candidates]))
    if len(metrics) > 1:
        raise GateInputError(f"mixed cost_metric values across the compared skills: {', '.join(sorted(metrics))}")

    results, passing = [], []
    cur = skills[current]
    for name in candidates:
        cand = skills[name]
        ungraded = cand.ungraded()
        if ungraded:
            results.append({"candidate": name, "keep": False,
                            "reason": f"ungraded run(s) on task(s) {', '.join(ungraded)}; every candidate run must be graded"})
            continue
        c = compare(cand, cur)
        keep, reason = verdict(c)
        results.append({"candidate": name, "keep": keep, "reason": reason, **c.__dict__})
        if keep:
            passing.append(c)

    winner = None
    if passing:
        best = max(passing, key=lambda c: c.acc_candidate)
        tied = [c for c in passing
                if c is best or best.acc_candidate - c.acc_candidate <= compare(skills[best.candidate], skills[c.candidate]).se + EPS]
        winner = min(tied, key=lambda c: (math.inf if c.cost_candidate is None else c.cost_candidate, -c.acc_candidate)).candidate
    return {"current": current, "cost_metric": next(iter(metrics), None), "winner": winner, "results": results}


def render(report: dict) -> str:
    out = [f"current skill: {report['current']}" + (f"  (cost in {report['cost_metric']})" if report["cost_metric"] else "")]
    for r in report["results"]:
        out.append(f"  {'KEEP  ' if r['keep'] else 'REJECT'} {r['candidate']}: {r['reason']}")
        if r.get("dropped_tasks"):
            out.append(f"         dropped (current skill ungraded): {', '.join(r['dropped_tasks'])}")
    out.append(f"winner: {report['winner']}" if report["winner"] else f"winner: none, keep {report['current']}")
    return "\n".join(out)


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description="Keep or reject a rewritten skill from graded runs.")
    p.add_argument("runs", type=Path, help="JSONL of runs, one per line")
    p.add_argument("--current", required=True, help="skill id of the version in use now")
    p.add_argument("--candidate", required=True, action="append", help="skill id of a rewrite (repeatable)")
    p.add_argument("--json", action="store_true", help="print the full report as JSON")
    a = p.parse_args(argv)
    try:
        report = judge(load(a.runs), a.current, a.candidate)
    except GateInputError as e:
        print(f"bad input: {e}", file=sys.stderr)
        return BAD_INPUT
    print(json.dumps(report, indent=2) if a.json else render(report))
    return KEEP if report["winner"] else REJECT


if __name__ == "__main__":
    sys.exit(main())

