#!/usr/bin/env python3
"""Planted cases with known answers, so a gate that always says KEEP (or always says
REJECT) fails here.

Elsewhere in this repo the tests break real data. There are no graded skill runs yet,
so these runs are synthetic: each case is built so the right verdict follows from the
rule by hand. The pairing case is the one that matters most. Two skills that rise and
fall together across tasks, one a constant 0.05 above the other, must be KEPT when
paired and called a tie when the same numbers are unpaired. If pairing were only a
label in the output, that case would fail.

    python test_gate.py
"""

from __future__ import annotations

import contextlib
import io
import json
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import gate  # noqa: E402

BASE = [0.1, 0.9, 0.3, 0.7, 0.5, 0.2, 0.8, 0.4]


def runs(skill, rewards, cost=0.03, prefix="t", metric="usd"):
    """One run per task (rep 0). rewards: a list, one value per task."""
    return [{"skill": skill, "task_id": f"{prefix}{i}", "rep": 0, "reward": r,
             "cost": cost, "cost_metric": metric} for i, r in enumerate(rewards)]


def call(rows, current, *candidates, raw=None):
    """Write rows to a temp JSONL, run main(), return (exit code, report or None)."""
    with tempfile.TemporaryDirectory() as d:
        p = Path(d) / "runs.jsonl"
        p.write_text(raw if raw is not None else "\n".join(json.dumps(r) for r in rows) + "\n", encoding="utf-8")
        args = [str(p), "--current", current, "--json"] + [x for c in candidates for x in ("--candidate", c)]
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            code = gate.main(args)
    return code, (json.loads(out.getvalue()) if out.getvalue().strip() else None)


def result(report, name):
    return next(r for r in report["results"] if r["candidate"] == name)


CASES = []


def case(fn):
    CASES.append(fn)
    return fn


@case
def clear_win():
    code, rep = call(runs("cur", BASE) + runs("new", [r + 0.3 for r in BASE], cost=0.09), "cur", "new")
    assert code == gate.KEEP and rep["winner"] == "new", rep
    assert result(rep, "new")["reason"].startswith("more accurate")


@case
def clear_loss():
    code, rep = call(runs("cur", BASE) + runs("new", [r - 0.3 for r in BASE], cost=0.001), "cur", "new")
    assert code == gate.REJECT and rep["winner"] is None, rep
    assert result(rep, "new")["reason"].startswith("less accurate")


TIE = [0.2, 0.8, 0.4, 0.6, 0.5, 0.1, 0.9, 0.3]  # same mean as BASE, noisy per task


@case
def tie_cheaper_keeps():
    code, rep = call(runs("cur", BASE, cost=0.03) + runs("new", TIE, cost=0.02), "cur", "new")
    assert code == gate.KEEP, rep
    assert "cheaper" in result(rep, "new")["reason"]


@case
def tie_not_cheaper_rejects():
    code, rep = call(runs("cur", BASE, cost=0.03) + runs("new", TIE, cost=0.03), "cur", "new")
    assert code == gate.REJECT and "not cheaper" in result(rep, "new")["reason"], rep


@case
def tie_null_cost_rejects():
    rows = runs("cur", BASE, cost=0.03) + runs("new", TIE, cost=0.02)
    rows[-1]["cost"] = None
    code, rep = call(rows, "cur", "new")
    assert code == gate.REJECT and "not comparable" in result(rep, "new")["reason"], rep


@case
def pairing_changes_the_answer():
    shifted = [r + 0.05 for r in BASE]
    code, rep = call(runs("cur", BASE) + runs("new", shifted, cost=0.04), "cur", "new")
    r = result(rep, "new")
    assert code == gate.KEEP and r["se_kind"] == "paired" and r["se"] < 1e-6, rep
    # Same numbers, but the task ids no longer line up, so the SE must be unpaired.
    code, rep = call(runs("cur", BASE) + runs("new", shifted, cost=0.04, prefix="u"), "cur", "new")
    r = result(rep, "new")
    assert r["se_kind"] == "unpaired" and r["se"] > 0.1, rep
    assert code == gate.REJECT and "not cheaper" in r["reason"], rep


@case
def repeats_average_per_task():
    # Task t0 has two reps for new (0 and 1) -> task mean 0.5; it must not count twice.
    rows = runs("cur", [0.5, 0.5, 0.5]) + runs("new", [0.0, 0.5, 0.5])
    rows.append({"skill": "new", "task_id": "t0", "rep": 1, "reward": 1.0, "cost": 0.03, "cost_metric": "usd"})
    code, rep = call(rows, "cur", "new")
    r = result(rep, "new")
    assert abs(r["acc_candidate"] - 0.5) < 1e-9 and r["n_candidate"] == 3, rep


@case
def candidate_ungraded_rejects():
    rows = runs("cur", BASE) + runs("new", [r + 0.3 for r in BASE])
    rows[-1]["reward"] = None
    code, rep = call(rows, "cur", "new")
    assert code == gate.REJECT and "ungraded" in result(rep, "new")["reason"], rep


@case
def current_ungraded_task_dropped_from_both():
    rows = runs("cur", BASE) + runs("new", [r + 0.05 for r in BASE], cost=0.04)
    rows[0]["reward"] = None  # current skill, task t0
    code, rep = call(rows, "cur", "new")
    r = result(rep, "new")
    assert r["dropped_tasks"] == ["t0"] and r["n_candidate"] == 7 and r["se_kind"] == "paired", rep
    assert code == gate.KEEP, rep


@case
def several_candidates_cheapest_of_the_tied_wins():
    cur = [0.1, 0.2, 0.1, 0.3, 0.2, 0.1]
    a = [0.9, 0.5, 0.8, 0.6, 0.9, 0.7]  # most accurate, expensive
    b = [0.8, 0.6, 0.7, 0.6, 0.8, 0.7]  # within one SE of a, cheap
    code, rep = call(runs("cur", cur) + runs("a", a, cost=0.09) + runs("b", b, cost=0.02), "cur", "a", "b")
    assert code == gate.KEEP and rep["winner"] == "b", rep


@case
def several_candidates_clearly_better_wins_despite_cost():
    cur = [0.1, 0.2, 0.1, 0.3, 0.2, 0.1]
    a = [0.9, 0.9, 0.8, 0.9, 0.9, 0.8]  # well beyond one SE of b
    b = [0.4, 0.5, 0.4, 0.5, 0.4, 0.5]
    code, rep = call(runs("cur", cur) + runs("a", a, cost=0.09) + runs("b", b, cost=0.02), "cur", "a", "b")
    assert code == gate.KEEP and rep["winner"] == "a", rep


@case
def candidate_tie_uses_the_same_tasks_as_the_gate():
    # Current skill is ungraded on t0, so t0 must not count when a and b are compared
    # either. On t0 alone, a beats b by 1.0; counting it would inflate the a-b SE so
    # much that b (cheaper, clearly worse on the other tasks) would wrongly tie and win.
    cur = [0.0, 0.1, 0.2, 0.1, 0.3, 0.2, 0.1]
    a = [1.0, 0.9, 0.9, 0.9, 0.9, 0.9, 0.9]
    b = [0.0, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5]
    rows = runs("cur", cur) + runs("a", a, cost=0.09) + runs("b", b, cost=0.02)
    rows[0]["reward"] = None
    code, rep = call(rows, "cur", "a", "b")
    assert code == gate.KEEP and rep["winner"] == "a", rep


def _bad(rows=None, current="cur", candidates=("new",), raw=None):
    code, rep = call(rows or [], current, *candidates, raw=raw)
    assert code == gate.BAD_INPUT and rep is None, (code, rep)


@case
def one_task_is_bad_input():
    _bad(runs("cur", [0.5]) + runs("new", [0.9]))


@case
def duplicate_run_is_bad_input():
    rows = runs("cur", BASE) + runs("new", BASE)
    _bad(rows + [rows[0]])


@case
def missing_field_is_bad_input():
    rows = runs("cur", BASE) + runs("new", BASE)
    del rows[3]["cost"]
    _bad(rows)


@case
def unknown_skill_is_bad_input():
    _bad(runs("cur", BASE) + runs("new", BASE), candidates=("typo",))


@case
def mixed_cost_metric_is_bad_input():
    _bad(runs("cur", BASE) + runs("new", BASE, metric="tokens"))


@case
def non_numeric_reward_is_bad_input():
    rows = runs("cur", BASE) + runs("new", BASE)
    rows[2]["reward"] = "1"
    _bad(rows)


@case
def bad_json_is_bad_input():
    _bad(raw='{"skill": "cur", "task_id": "t0"\n')


@case
def example_file_runs():
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        code = gate.main([str(Path(__file__).with_name("example.jsonl")), "--current", "base",
                          "--candidate", "v2", "--candidate", "v3"])
    assert code == gate.KEEP and "winner: v2" in out.getvalue(), out.getvalue()


def main() -> int:
    failed = 0
    for fn in CASES:
        try:
            fn()
            print(f"  ok    {fn.__name__}")
        except AssertionError as e:
            failed += 1
            print(f"  FAIL  {fn.__name__}: {e}")
    print(f"{len(CASES) - failed}/{len(CASES)} passed")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

